input.command:
mkdir -p resources && cat > Caddyfile <<'EOF'
{
	admin off
}

:8089 {
	resource {
		dir resources
		dsn postgres://eval_rw:eval_rw@postgres:5432/llmapi_eval
		formats json csv
		envelope {
			items items
			total total
			page page
			itemsPerPage itemsPerPage
		}
		errors {
			error message
		}
		error_details off
	}
}
EOF
cat > start.sh <<'EOF'
#!/bin/sh
# Serves the bookshop API on http://localhost:8089 in the foreground.
cd "$(dirname "$0")" && exec ./caddy run --config Caddyfile
EOF
chmod +x start.sh

