input.command:
cd /tmp/intro && cat > resources/Cleanup.json <<'EOF'
{
  "name": "Cleanup",
  "path": "/cleanup",
  "query": "cleanup.query.ts",
  "command": "cleanup.command.ts",
  "properties": {"id": {"type": "integer", "identifier": true}}
}
EOF
cat > resources/cleanup.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`SELECT 1 AS id`;
}
EOF
cat > resources/cleanup.command.ts <<'EOF'
export function create(input, ctx) {
  ctx.db.exec(ctx.sql`UPDATE book b SET stock = b.stock + agg.q
    FROM (SELECT pl.book_id, sum(pl.quantity)::int AS q FROM purchase_line pl JOIN purchase p ON p.id = pl.purchase_id
          WHERE p.customer_id = 4 GROUP BY pl.book_id) agg
    WHERE b.id = agg.book_id`);
  ctx.db.exec(ctx.sql`DELETE FROM purchase_line WHERE purchase_id IN (SELECT id FROM purchase WHERE customer_id = 4)`);
  ctx.db.exec(ctx.sql`DELETE FROM purchase WHERE customer_id = 4`);
  return 1;
}
EOF
(./caddy run --config Caddyfile > caddy.log 2>&1 & echo $! > /tmp/intro.pid); sleep 3
echo '--- before'; curl -s localhost:8190/rcust | grep -o '"id":4[^}]*'; curl -s localhost:8190/rbooks | tr '}' '\n' | grep -o '"id":[0-9]*,"title":"[^"]*".*"stock":[0-9]*' | sed -E 's/"author_id.*"stock"/ stock/' | grep -E '"id":(1|4|18),'
curl -s -w ' %{http_code}\n' -X POST localhost:8190/cleanup -H 'Content-Type: application/json' -d '{}'
echo '--- after'; curl -s localhost:8190/rcust | grep -o '"id":4[^}]*'; curl -s localhost:8190/rbooks | tr '}' '\n' | grep -o '"id":[0-9]*,"title":"[^"]*".*"stock":[0-9]*' | sed -E 's/"author_id.*"stock"/ stock/' | grep -E '"id":(1|4|18),'
kill $(cat /tmp/intro.pid) && echo "intro stopped"
